package ro.leo.visual;
import ro.leo.i18n.L;import org.json.*;import java.util.*;import java.io.*;
public final class StreamRadioActivity extends PocketActivity {
 protected void render()throws Exception{JSONObject data=PocketStore.read(this,"streams");final JSONArray stations=data.optJSONArray("stations")==null?new JSONArray():data.getJSONArray("stations");ArrayList<String> labels=new ArrayList<>();labels.add(L.t("Adaugă post"));labels.add(L.t("Media curentă"));for(int n=0;n<stations.length();n++)labels.add(stations.getJSONObject(n).optString("name")+"\n"+stations.getJSONObject(n).optString("url"));list(L.t("Radio Internet"),labels,0,new Choice(){public void pick(final int at){if(at==0)add();else if(at==1)startActivity(new android.content.Intent(StreamRadioActivity.this,NowPlayingActivity.class));else try{final JSONObject station=stations.getJSONObject(at-2);options(station.optString("name"),new String[]{L.t("Ascultă"),L.t("Piesa curentă · ICY"),L.t("Șterge postul")},new Choice(){public void pick(int action){if(action==0)try{FeedsActivity.play(StreamRadioActivity.this,station.optString("url"),station.optString("name"));}catch(Exception e){problem(e);}else if(action==1){final String[] info={""};job(L.t("Citesc metadatele radio"),new Work(){public void run()throws Exception{info[0]=IcyMetadata.sample(station.optString("url"));}},new Runnable(){public void run(){page(station.optString("name"),info[0],goHome(),"",null);}});}else remove(L.t("Ștergi postul?"),new Runnable(){public void run(){try{JSONArray next=new JSONArray();for(int n=0;n<stations.length();n++)if(n!=at-2)next.put(stations.get(n));PocketStore.write(StreamRadioActivity.this,"streams",new JSONObject().put("stations",next));home();}catch(Exception e){problem(e);}}});}});}catch(Exception e){problem(e);}}},L.t("Informații"),new Runnable(){public void run(){page(L.t("Radio Internet"),L.t("Adaugă adresa directă MP3/AAC a postului. Redarea folosește date mobile sau Wi-Fi. Piesa curentă poate fi cerută separat, dacă postul trimite metadate ICY. Listele M3U/PLS nu sunt interpretate."),goHome(),"",null);}});}
 private void add(){edit(L.t("Post nou"),new String[]{L.t("Nume"),L.t("Adresă directă MP3 / AAC")},new String[]{"","https://"},new Saved(){public void save(String[] v)throws Exception{String url=PocketStore.url(v[1]);if(v[0].trim().isEmpty())throw new IOException("Name required");JSONObject data=PocketStore.read(StreamRadioActivity.this,"streams");JSONArray stations=data.optJSONArray("stations");if(stations==null)stations=new JSONArray();if(stations.length()>=100)throw new IOException("Maximum 100 stations");stations.put(new JSONObject().put("name",v[0].trim()).put("url",url));PocketStore.write(StreamRadioActivity.this,"streams",data.put("stations",stations));home();}},goHome());}
}
